// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this)); // actor is not the admin/deployer
        vm.prank(address(this));
        c.setOwner(actor); // admin transfers ownership to actor
        vm.prank(actor); // the current (non-admin) owner attempts to change owner
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok); // only the immutable admin may ever change owner
    }
}
